effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

vec3 termico(float t) {
    t = clamp(t, 0.0, 1.0);
    vec3 preto = vec3(0.0, 0.0, 0.05);
    vec3 roxo  = vec3(0.25, 0.0, 0.5);
    vec3 azul  = vec3(0.0, 0.3, 0.8);
    vec3 verde = vec3(0.0, 0.8, 0.2);
    vec3 amar  = vec3(1.0, 0.9, 0.0);
    vec3 laran = vec3(1.0, 0.45, 0.0);
    vec3 verm  = vec3(1.0, 0.1, 0.1);
    vec3 branco = vec3(1.0);
    if (t < 0.15) return mix(preto, roxo, t / 0.15);
    if (t < 0.30) return mix(roxo, azul, (t - 0.15) / 0.15);
    if (t < 0.50) return mix(azul, verde, (t - 0.30) / 0.20);
    if (t < 0.65) return mix(verde, amar, (t - 0.50) / 0.15);
    if (t < 0.80) return mix(amar, laran, (t - 0.65) / 0.15);
    if (t < 0.92) return mix(laran, verm, (t - 0.80) / 0.12);
    return mix(verm, branco, (t - 0.92) / 0.08);
}

void main() {
    vec4 c = texture(inputImg, acScreenNorm);
    float l = clamp(dot(c.rgb, LUMA) + brightness, 0.0, 1.0);
    l = pow(l, gamma);
    vec3 cor = termico(l);
    fragColor = vec4(mix(c.rgb, cor, blend), c.a);
}
